#include <stdio.h>
int main(void) {
    int v[] = {3, 1, 2};
    for (int i = 0; i < 3; i++) {
        int menor = i;
        for (int j = i + 1; j < 3; j++)
            if (v[j] < v[menor]) menor = j;
        int tmp = v[i]; v[i] = v[menor]; v[menor] = tmp;
    }
    printf("%d\n", v[0]);
    return 0;
}

